cat > /app/tmp/repro.rb <<'EOF'
def check(label)
  result = yield
  puts "OK    #{label} => #{result.inspect}"
rescue => e
  puts "FAIL  #{label} => #{e.class}: #{e.message.lines.first.strip}"
end

book = Book.first || Book.create!(title: "T", slug: "t")
t = book.updated_at || Time.zone.now

puts "--- date/time conversions (old style) ---"
check("TimeWithZone#to_s(:number)  [reports_controller card_filename]") { t.to_s(:number) }
check("Date#to_s(:long)            [reports_helper report_stamp]") { t.to_date.to_s(:long) }
check("Date#to_s(:short)           [digest mailer view]") { t.to_date.to_s(:short) }

puts "--- number conversions (old style) ---"
check("Integer#to_s(:delimited)    [book.report_summary]") { book.markable.length.to_s(:delimited) }

puts "--- list of records (old style) ---"
