puts "--- report card render (old style) ---"
check("ReportCard render TimeWithZone#to_s(:long)") { book.created_at.to_s(:long) }
check("ReportCard render TimeWithZone#to_s(:short)") { book.updated_at.to_s(:short) }

puts "--- archive job timestamp (old style) ---"
